/bin/bash -lc "node --input-type=module <<'EOF'
import { processJob, retriesEnabled } from './src/worker.js';
const events=[];
const job={id:'j1',execute:async()=>{events.push('execute'); return 7;}};
const queue={ack:async id=>events.push('ack')};
const ledger={record:async()=>{events.push('record'); throw new Error('ledger unavailable')}};
try { await processJob(job,queue,ledger); } catch (e) { console.log('processJob error:',e.message); }
console.log('events:',events.join(' -> '));
console.log('retry values:', retriesEnabled({RETRIES_ENABLED:'false'}), retriesEnabled({RETRIES_ENABLED:'0'}), retriesEnabled({}));
EOF
node --check src/worker.js && node --check ops/start-worker.js && node --check test/smoke.test.js"

